(function(root){'use strict';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function create({container,getState,changed,practice,when}){
 let tag='',setId=null,trash=false,query='',group='all',status='all',page=0,selected=new Set();
 const dialog=document.createElement('dialog');dialog.className='library-dialog';document.body.append(dialog);
 const data=()=>getState().catalog;
 const tagsMarkup=s=>'<div class="set-tags">'+(s.tags||[]).map(t=>'<span class="set-tag">'+esc(t)+'</span>').join('')+'</div>';
 function tagFilter(){const tags=[...new Set(data().sets.filter(s=>s.deleted===trash).flatMap(s=>s.tags||[]))].sort((a,b)=>a.localeCompare(b,'zh'));if(tag&&!tags.includes(tag))tag='';return '<select id="set-tag-filter" aria-label="按标签筛选句集"><option value="">全部标签</option>'+tags.map(t=>'<option value="'+esc(t)+'" '+(tag===t?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select>';}

 const uid=prefix=>prefix+'-'+crypto.randomUUID();
 function commit(){changed();render();}
 function modal(title,body,onSave){dialog.innerHTML='<form><div class="dialog-head"><h2>'+esc(title)+'</h2><button type="button" class="icon-button" aria-label="关闭编辑">×</button></div>'+body+'<div class="settings-actions"><button class="primary">保存</button></div><p class="form-error" role="status"></p></form>';dialog.querySelector('.icon-button').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{onSave(new FormData(e.currentTarget));dialog.close();commit();}catch(err){dialog.querySelector('.form-error').textContent=err.message;}};dialog.showModal();}
 function editSet(id){const s=data().sets.find(s=>s.id===id);modal(s?'编辑句集':'新建句集',`<label>句集名称<input name="name" maxlength="100" required value="${esc(s?.name||'')}" placeholder="例如：工作日常"></label><label>简介<textarea name="description" maxlength="1000" rows="3">${esc(s?.description||'')}</textarea></label><label>标签<input name="tags" maxlength="619" value="${esc((s?.tags||[]).join('，'))}" placeholder="例如：口语，写作，旅行"><span class="muted">用逗号分隔；清空即可移除标签。最多 20 个，每个 30 字。</span></label><label class="check-label"><input type="checkbox" name="active" ${s?.active?'checked':''}> 加入每日练习（多个句集合计新学目标）</label>`,f=>{const name=f.get('name').trim();if(!name)throw Error('请输入句集名称');const tags=root.ParoleCollections.normalizeTags(f.get('tags').split(/[,，]/).map(t=>t.trim()).filter(Boolean));const values={name,tags,description:f.get('description').trim(),active:f.has('active')};if(s)Object.assign(s,values);else{if(data().sets.length>=1000)throw Error('最多支持 1000 个句集');const id=uid('set');data().sets.push({id,...values,deleted:false});setId=id;query='';trash=false;}});}
 function editCard(id){const c=data().cards.find(c=>c.id===id),s=data().sets.find(s=>s.id===(c?.setId||setId));if(!s||s.deleted)return;
 const groups=[...new Set(data().cards.filter(c=>c.setId===s.id&&!c.deleted).map(c=>c.group))];
 modal(c?'编辑表达':'添加表达',`<label>题目提示<textarea name="zh" required maxlength="2000" rows="2">${esc(c?.zh||'')}</textarea></label><label>参考表达<textarea name="fr" lang="fr" required maxlength="2000" rows="3">${esc(c?.fr||'')}</textarea></label><label>类别<input name="group" required maxlength="100" list="category-options" value="${esc(c?.group||'通用表达')}"></label><datalist id="category-options">${groups.map(g=>'<option value="'+esc(g)+'"></option>').join('')}</datalist><label>补充说明<textarea name="note" maxlength="2000" rows="2">${esc(c?.note||'')}</textarea></label><label class="check-label"><input type="checkbox" name="star" ${c?.star?'checked':''}> 优先掌握</label><p class="muted">修改会保留学习历史、笔记和复习日期。旧历史仍使用当时的参考表达。</p>`,f=>{const v={zh:f.get('zh').trim(),fr:f.get('fr').trim(),group:f.get('group').trim(),note:f.get('note').trim(),star:f.has('star')};if(!v.zh||!v.fr||!v.group)throw Error('题目、参考表达和类别不能为空');if(c)Object.assign(c,v);else{if(data().cards.length>=20000)throw Error('最多支持 20000 条表达');data().cards.push({id:uid('expr'),setId:s.id,deleted:false,...v});}});
 const languages=root.ParoleLanguages.normalize(getState().settings);dialog.querySelector('[name=zh]').lang=languages.sourceLanguage;dialog.querySelector('[name=fr]').lang=languages.targetLanguage;
 if(!c)root.ParoleGeneratorUI.attach({dialog,getState,setId:s.id,onAdded:result=>{query='';group='all';status='all';page=0;commit();const message=document.createElement('p');message.className='muted';message.setAttribute('role','status');message.textContent=`已添加 ${result.cards.length} 条表达，跳过 ${result.skipped} 条重复表达。`;container.prepend(message);}});
 }
 function archiveSet(id){const s=data().sets.find(s=>s.id===id);if(!s)return;s.deleted=true;s.active=false;commit();}
 function restoreSet(id){const s=data().sets.find(s=>s.id===id);s.deleted=false;s.active=false;commit();}
 function purgeSet(id){const s=data().sets.find(s=>s.id===id);if(!confirm('彻底删除「'+s.name+'」及其全部表达、评分和笔记？此操作无法恢复。'))return;root.ParoleCollections.removeForever(getState(),data().cards.filter(c=>c.setId===id).map(c=>c.id));data().sets=data().sets.filter(s=>s.id!==id);commit();}
 function editSelection(action){const cards=data().cards.filter(c=>selected.has(c.id));if(!cards.length)return;
  if(action==='move'){const targets=data().sets.filter(s=>!s.deleted&&s.id!==setId);if(!targets.length){alert('请先新建另一个句集。');return;}modal('移动 '+cards.length+' 条表达',`<label>目标句集<select name="target">${targets.map(s=>'<option value="'+s.id+'">'+esc(s.name)+'</option>').join('')}</select></label><p class="muted">移动后保留学习记录，并遵循目标句集的练习开关。</p>`,f=>{cards.forEach(c=>c.setId=f.get('target'));selected.clear();});return;}
  if(action==='purge'){if(!confirm('彻底删除选中的 '+cards.length+' 条表达及其评分、笔记？无法恢复。'))return;root.ParoleCollections.removeForever(getState(),cards.map(c=>c.id));}
  else cards.forEach(c=>c.deleted=action==='delete');selected.clear();commit();
 }
 function render(){
  const s=data().sets.find(s=>s.id===setId&&!s.deleted);if(setId&&!s)setId=null;
  container.innerHTML='<div class="collection-head"><div><h2 '+(s?'data-study-content':'')+'>'+esc(s?s.name:'我的句集')+'</h2><p class="muted" '+(s?'data-study-content':'')+'>'+(s?esc(s.description||'按类别整理自己的表达。'):'可同时选择多个句集；未选中则暂停，复习日期和进度保留。')+'</p></div><div>'+(s?'<button class="secondary" data-action="back">← 全部句集</button><button class="primary" data-action="add-card">添加表达</button>':'<button class="primary" data-action="add-set">新建句集</button>')+'</div></div>';
  if(s){container.insertAdjacentHTML('beforeend',tagsMarkup(s)+'<p class="collection-context">'+(s.active?'已加入每日练习':'已暂停练习')+' · 每日新学目标由所有选中句集共用。 <button class="text-button" data-action="toggle-current">'+(s.active?'暂停此句集':'加入练习')+'</button> <button class="text-button" data-action="edit-set">编辑句集</button></p>');}
  container.insertAdjacentHTML('beforeend',`<div class="library-toolbar"><input id="collection-search" type="search" placeholder="${s?'搜索题目、参考表达或编号':'搜索句集名称、简介或标签'}" aria-label="${s?'搜索表达':'搜索句集'}" value="${esc(query)}"><button class="secondary" data-action="trash">${trash?'返回正常列表':'回收站'}</button>${s?`<select id="collection-group" aria-label="筛选类别"><option value="all">全部类别</option>${[...new Set(data().cards.filter(c=>c.setId===s.id).map(c=>c.group))].map(g=>'<option value="'+esc(g)+'" '+(group===g?'selected':'')+'>'+esc(g)+'</option>').join('')}</select><select id="collection-status" aria-label="筛选学习状态">${[['all','全部状态'],['new','还没学过'],['due','已经到期'],['weak','需要巩固 ≤5 分'],['star','优先掌握 ★']].map(([v,n])=>'<option value="'+v+'" '+(status===v?'selected':'')+'>'+n+'</option>').join('')}</select>`:tagFilter()}</div><div id="collection-results"></div>`);
  container.querySelector('#set-tag-filter')?.addEventListener('change',e=>{tag=e.target.value;results();});
  container.querySelector('#collection-search').oninput=e=>{query=e.target.value;page=0;selected.clear();results();};
  container.querySelector('#collection-group')?.addEventListener('change',e=>{group=e.target.value;page=0;selected.clear();results();});
  container.querySelector('#collection-status')?.addEventListener('change',e=>{status=e.target.value;page=0;selected.clear();results();});
  container.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case 'back':setId=null;query='';trash=false;break;case 'add-set':editSet();return;case 'add-card':editCard();return;case 'edit-set':editSet(setId);return;case 'toggle-current':s.active=!s.active;commit();return;case 'trash':trash=!trash;query='';break;}page=0;selected.clear();render();});results();
 }
 function results(){const box=container.querySelector('#collection-results'),state=getState(),q=query.toLocaleLowerCase(),s=data().sets.find(s=>s.id===setId);if(!s){
  const list=data().sets.filter(s=>s.deleted===trash&&(!tag||(s.tags||[]).includes(tag))&&(!q||(s.name+' '+s.description+' '+(s.tags||[]).join(' ')).toLocaleLowerCase().includes(q)));
  box.innerHTML='<p class="list-count">'+(trash?'已归档句集':'句集')+' · '+list.length+' 个</p><div class="library-list">'+list.map(s=>{const cards=data().cards.filter(c=>c.setId===s.id&&!c.deleted),learned=cards.filter(c=>state.progress[c.id]).length,due=cards.filter(c=>state.progress[c.id]?.due<=Date.now()).length;return '<article class="library-card"><h3 data-study-content>'+esc(s.name)+'</h3>'+tagsMarkup(s)+'<p class="note" data-study-content>'+esc(s.description)+'</p><p class="muted">'+cards.length+' 条 · 已学 '+learned+' 条 · '+(s.active&&!s.deleted?'到期复习 ':'暂停中，已到期 ')+due+' 条</p>'+(trash?'<button class="secondary" data-restore-set="'+s.id+'">恢复句集</button><button class="text-button" data-purge-set="'+s.id+'">彻底删除</button>':'<label class="check-label"><input type="checkbox" data-active="'+s.id+'" '+(s.active?'checked':'')+'> 加入每日练习</label><div class="library-bottom"><button class="primary" data-open="'+s.id+'">打开句集 →</button><button class="text-button" data-edit-set="'+s.id+'">编辑</button><button class="text-button" data-delete-set="'+s.id+'">归档</button></div>')+'</article>';}).join('')+'</div>'+(!list.length?'<p class="empty-state">'+(trash?'回收站为空。':'没有匹配的句集，试试新建或修改搜索。')+'</p>':'');
  box.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{setId=b.dataset.open;query='';group='all';status='all';trash=false;page=0;selected.clear();render();});
  box.querySelectorAll('[data-active]').forEach(b=>b.onchange=()=>{data().sets.find(s=>s.id===b.dataset.active).active=b.checked;commit();});
  for(const [attr,fn] of [['edit-set',editSet],['delete-set',archiveSet],['restore-set',restoreSet],['purge-set',purgeSet]])box.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=()=>fn(b.getAttribute('data-'+attr)));return;
 }
 const filtered=data().cards.filter(c=>{const p=state.progress[c.id];return c.setId===s.id&&c.deleted===trash&&(group==='all'||c.group===group)&&(!q||(c.zh+' '+c.fr+' '+c.id).toLocaleLowerCase().includes(q))&&(status==='all'||status==='new'&&!p||status==='due'&&p&&p.due<=Date.now()||status==='weak'&&p&&p.lastScore<=5||status==='star'&&c.star);});
 const pages=Math.max(1,Math.ceil(filtered.length/20));page=Math.min(page,pages-1);const visible=filtered.slice(page*20,page*20+20);
 box.innerHTML=`<div class="bulk-actions"><label class="check-label"><input id="select-page" type="checkbox" ${visible.length&&visible.every(c=>selected.has(c.id))?'checked':''}> 选择本页</label><span>共 ${filtered.length} 条 · 已选 ${selected.size} 条</span>${trash?'<button class="secondary" data-bulk="restore">恢复所选</button><button class="secondary" data-bulk="purge">彻底删除所选</button>':'<button class="secondary" data-bulk="move">移动所选</button><button class="secondary" data-bulk="delete">删除所选</button>'}</div><div class="library-list">${visible.map(c=>{const p=state.progress[c.id];return `<article class="library-card"><div class="card-top"><label class="check-label"><input type="checkbox" data-select="${c.id}" ${selected.has(c.id)?'checked':''} aria-label="选择表达 ${esc(c.zh)}"> ${esc(c.group)}</label><span class="card-id">${c.star?'★ ':''}${esc(c.id)}</span></div><h3 data-study-content>${esc(c.zh)}</h3><details><summary>查看参考表达</summary><p class="fr" lang="fr">${esc(c.fr)}</p><p class="note" data-study-content>${esc(c.note)}</p></details><div class="library-bottom"><span>${p?'上次 '+p.lastScore+' 分 · '+(s.active?when(p.due):'已暂停'):'还没学过'}</span>${trash?`<button class="text-button" data-restore="${c.id}">恢复表达</button>`:`<button class="text-button" data-practice="${c.id}" ${s.active?'':'disabled'}>${s.active?'练这一条 ↗':'句集已暂停'}</button>`}</div>${!trash?`<div class="library-bottom"><button class="text-button" data-edit="${c.id}">编辑表达</button><button class="text-button" data-delete="${c.id}">删除表达</button>${p?`<button class="text-button" data-reset="${c.id}">重置复习计划</button>`:''}</div>`:''}</article>`;}).join('')}</div>${!filtered.length?'<p class="empty-state">没有匹配的表达。</p>':''}<div class="pagination"><button class="secondary" id="collection-prev" ${page===0?'disabled':''}>上一页</button><span>${page+1} / ${pages}</span><button class="secondary" id="collection-next" ${page===pages-1?'disabled':''}>下一页</button></div>`;
 box.querySelector('#select-page').onchange=e=>{visible.forEach(c=>e.target.checked?selected.add(c.id):selected.delete(c.id));results();};box.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);results();});box.querySelectorAll('[data-bulk]').forEach(b=>{b.disabled=!selected.size;b.onclick=()=>editSelection(b.dataset.bulk);});
 box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCard(b.dataset.edit));box.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>practice(b.dataset.practice));
 for(const action of ['delete','restore'])box.querySelectorAll('[data-'+action+']').forEach(b=>b.onclick=()=>{const c=data().cards.find(c=>c.id===b.getAttribute('data-'+action));c.deleted=action==='delete';selected.delete(c.id);commit();});
 box.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{if(!confirm('重新安排这条表达的复习？历史评分和笔记会保留，表达会立即进入到期复习。'))return;getState().progress[b.dataset.reset]={...root.ParoleCore.schedule(null,1),due:Date.now()};commit();});
 box.querySelector('#collection-prev').onclick=()=>{page--;selected.clear();results();};box.querySelector('#collection-next').onclick=()=>{page++;selected.clear();results();};
 }
 return {render,refresh(){selected.clear();render();}};
}
root.ParoleLibrary={create};
})(window);
